import React, { useEffect, useState } from "react";
import axios from "axios";

import {
  Card,
  CardContent,
  Typography,
  Grid,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Chip,
  TextField,
  Box,
  AppBar,
  Toolbar,
  Avatar,
  Drawer,
  Divider,
  List,
  ListItem,
  ListItemText,
  Button,
} from "@mui/material";

import {
  Warning,
  CheckCircle,
  Error,
} from "@mui/icons-material";

function Dashboard() {

  const [buyers, setBuyers] = useState([]);
  const [search, setSearch] = useState("");

  const [selectedBuyer, setSelectedBuyer] = useState(null);
  const [drawerOpen, setDrawerOpen] = useState(false);

  const [riskFilter, setRiskFilter] = useState("ALL");
  const [vpnFilter, setVpnFilter] = useState(false);
  const [promoFilter, setPromoFilter] = useState(false);

  useEffect(() => {
    axios
      .get("http://localhost:8000/buyers")
      .then((response) => {
        setBuyers(response.data);
      })
      .catch((error) => {
        console.error(error);
      });
  }, []);

  const filteredBuyers = buyers.filter((buyer) => {

    const matchesSearch =
      buyer.name
        ?.toLowerCase()
        .includes(search.toLowerCase());

    const buyerRisk =
      buyer.risk_level
        ?.toString()
        .trim()
        .toUpperCase();

    const selectedRisk =
      riskFilter
        ?.toString()
        .trim()
        .toUpperCase();

    const matchesRisk =
      selectedRisk === "ALL"
        ? true
        : buyerRisk === selectedRisk;

    const matchesVPN =
      vpnFilter
        ? buyer.vpn_detected === true
        : true;

    const matchesPromo =
      promoFilter
        ? buyer.promo_abuse === true
        : true;

    return (
      matchesSearch &&
      matchesRisk &&
      matchesVPN &&
      matchesPromo
    );
  });

  const greenCount = buyers.filter(
    (b) =>
      b.risk_level?.trim()?.toUpperCase() === "GREEN"
  ).length;

  const amberCount = buyers.filter(
    (b) =>
      b.risk_level?.trim()?.toUpperCase() === "AMBER"
  ).length;

  const redCount = buyers.filter(
    (b) =>
      b.risk_level?.trim()?.toUpperCase() === "RED"
  ).length;

  const getChipColor = (level) => {
    const cleanLevel =
      level?.trim()?.toUpperCase();

    if (cleanLevel === "RED") return "error";
    if (cleanLevel === "AMBER") return "warning";

    return "success";
  };

  const openBuyerDrawer = (buyer) => {
    setSelectedBuyer(buyer);
    setDrawerOpen(true);
  };

  const resetFilters = () => {
    setRiskFilter("ALL");
    setVpnFilter(false);
    setPromoFilter(false);
    setSearch("");
  };

  const generateRiskReasons = (buyer) => {
    const generateRelationshipSignals = (buyer) => {

  const relatedSignals = [];

  const sameIPCount = buyers.filter(
    (b) =>
      b.ip_address === buyer.ip_address
  ).length;

  if (sameIPCount > 1) {
    relatedSignals.push(
      `${sameIPCount} buyers linked to same IP`
    );
  }

  const sameFingerprintCount = buyers.filter(
    (b) =>
      b.device_fingerprint ===
      buyer.device_fingerprint
  ).length;

  if (sameFingerprintCount > 1) {
    relatedSignals.push(
      `${sameFingerprintCount} buyers sharing device fingerprint`
    );
  }

  const promoAbuseCount = buyers.filter(
    (b) =>
      b.promo_abuse === true
  ).length;

  if (
    buyer.promo_abuse &&
    promoAbuseCount > 1
  ) {
    relatedSignals.push(
      `${promoAbuseCount} promo abuse linked buyers`
    );
  }

  if (buyer.shared_accounts > 5) {
    relatedSignals.push(
      `High account linkage detected`
    );
  }

  return relatedSignals;
};

    const reasons = [];

    if (buyer.vpn_detected)
      reasons.push("VPN detected");

    if (buyer.shared_accounts > 5)
      reasons.push("Multiple linked accounts");

    if (parseInt(buyer.return_ratio) > 50)
      reasons.push("High return ratio");

    if (buyer.address_quality === "GARBLED")
      reasons.push("Garbled address");

    if (buyer.orders_last_24h > 10)
      reasons.push("Abnormal order velocity");

    if (buyer.promo_abuse)
      reasons.push("Promo abuse pattern");

    if (buyer.delivery_failures > 3)
      reasons.push("Repeated delivery failures");

    return reasons;
  };

  return (
    <Box
      sx={{
        backgroundColor: "#f4f6f8",
        minHeight: "100vh",
      }}
    >

      <AppBar
        position="static"
        sx={{
          backgroundColor: "#0f172a",
        }}
      >
        <Toolbar>

          <Avatar sx={{ mr: 2 }}>
            R
          </Avatar>

          <Divider
  sx={{
    marginTop: 2,
    marginBottom: 2,
  }}
/>

<Typography
  variant="h6"
  sx={{ marginBottom: 1 }}
>
  Linked Fraud Intelligence
</Typography>

<List>

  {generateRelationshipSignals(
    selectedBuyer
  ).length > 0 ? (

    generateRelationshipSignals(
      selectedBuyer
    ).map((signal, index) => (

      <ListItem key={index}>

        <Chip
          label={signal}
          color="error"
          sx={{ width: "100%" }}
        />

      </ListItem>

    ))

  ) : (

    <Typography variant="body2">
      No linked fraud signals detected.
    </Typography>

  )}

</List>

          <Typography variant="h6">
            Ecommerce Buyer Risk Dashboard
          </Typography>

        </Toolbar>
      </AppBar>

      <Box sx={{ padding: 4 }}>

        <Grid container spacing={3}>

          <Grid item xs={12} md={4}>
            <Card sx={{ borderRadius: 4 }}>
              <CardContent>

                <Typography variant="h6">
                  Low Risk Buyers
                </Typography>

                <Typography
                  variant="h3"
                  color="green"
                >
                  {greenCount}
                </Typography>

                <CheckCircle color="success" />

              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} md={4}>
            <Card sx={{ borderRadius: 4 }}>
              <CardContent>

                <Typography variant="h6">
                  Medium Risk Buyers
                </Typography>

                <Typography
                  variant="h3"
                  color="orange"
                >
                  {amberCount}
                </Typography>

                <Warning color="warning" />

              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} md={4}>
            <Card sx={{ borderRadius: 4 }}>
              <CardContent>

                <Typography variant="h6">
                  High Risk Buyers
                </Typography>

                <Typography
                  variant="h3"
                  color="red"
                >
                  {redCount}
                </Typography>

                <Error color="error" />

              </CardContent>
            </Card>
          </Grid>

        </Grid>

        <Card
          sx={{
            marginTop: 4,
            borderRadius: 4,
          }}
        >

          <CardContent>

            <Box
              sx={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                gap: 2,
                marginBottom: 3,
                flexWrap: "wrap",
              }}
            >

              <Typography variant="h6">
                Buyer Investigation Queue
              </Typography>

              <Box
                sx={{
                  display: "flex",
                  gap: 2,
                  alignItems: "center",
                  flexWrap: "wrap",
                }}
              >

                <TextField
                  size="small"
                  placeholder="Search buyer"
                  value={search}
                  onChange={(e) =>
                    setSearch(e.target.value)
                  }
                />

                <select
                  value={riskFilter}
                  onChange={(e) =>
                    setRiskFilter(e.target.value)
                  }
                  style={{
                    padding: "10px",
                    borderRadius: "8px",
                    border: "1px solid #ccc",
                    minWidth: "120px",
                    fontSize: "14px",
                  }}
                >
                  <option value="ALL">
                    ALL
                  </option>

                  <option value="RED">
                    RED
                  </option>

                  <option value="AMBER">
                    AMBER
                  </option>

                  <option value="GREEN">
                    GREEN
                  </option>

                </select>

                <Button
                  variant={
                    vpnFilter
                      ? "contained"
                      : "outlined"
                  }
                  color="error"
                  onClick={() =>
                    setVpnFilter(!vpnFilter)
                  }
                >
                  VPN Buyers
                </Button>

                <Button
                  variant={
                    promoFilter
                      ? "contained"
                      : "outlined"
                  }
                  color="warning"
                  onClick={() =>
                    setPromoFilter(!promoFilter)
                  }
                >
                  Promo Abuse
                </Button>

                <Button
                  variant="outlined"
                  color="secondary"
                  onClick={resetFilters}
                >
                  Reset Filters
                </Button>

              </Box>

            </Box>

            <TableContainer component={Paper}>

              <Table>

                <TableHead>

                  <TableRow>

                    <TableCell><b>Buyer ID</b></TableCell>
                    <TableCell><b>Name</b></TableCell>
                    <TableCell><b>Risk</b></TableCell>
                    <TableCell><b>IP Address</b></TableCell>
                    <TableCell><b>Fingerprint</b></TableCell>
                    <TableCell><b>Shared Accounts</b></TableCell>
                    <TableCell><b>Return Ratio</b></TableCell>
                    <TableCell><b>Orders 24H</b></TableCell>
                    <TableCell><b>Address</b></TableCell>
                    <TableCell><b>VPN</b></TableCell>
                    <TableCell><b>Promo Abuse</b></TableCell>
                    <TableCell><b>Delivery Failures</b></TableCell>

                  </TableRow>

                </TableHead>

                <TableBody>

                  {filteredBuyers.map((buyer) => (

                    <TableRow
                      key={buyer.id}
                      hover
                      onClick={() =>
                        openBuyerDrawer(buyer)
                      }
                      style={{
                        cursor: "pointer",
                      }}
                    >

                      <TableCell>
                        {buyer.id}
                      </TableCell>

                      <TableCell>
                        {buyer.name}
                      </TableCell>

                      <TableCell>
                        <Chip
                          label={buyer.risk_level}
                          color={getChipColor(
                            buyer.risk_level
                          )}
                        />
                      </TableCell>

                      <TableCell>
                        {buyer.ip_address}
                      </TableCell>

                      <TableCell>
                        {buyer.device_fingerprint}
                      </TableCell>

                      <TableCell>
                        <Chip
                          label={buyer.shared_accounts}
                          color={
                            buyer.shared_accounts > 5
                              ? "error"
                              : buyer.shared_accounts > 2
                              ? "warning"
                              : "success"
                          }
                        />
                      </TableCell>

                      <TableCell>
                        <Chip
                          label={buyer.return_ratio}
                          color={
                            parseInt(
                              buyer.return_ratio
                            ) > 50
                              ? "error"
                              : parseInt(
                                  buyer.return_ratio
                                ) > 20
                              ? "warning"
                              : "success"
                          }
                        />
                      </TableCell>

                      <TableCell>
                        <Chip
                          label={buyer.orders_last_24h}
                          color={
                            buyer.orders_last_24h > 10
                              ? "error"
                              : buyer.orders_last_24h > 5
                              ? "warning"
                              : "success"
                          }
                        />
                      </TableCell>

                      <TableCell>
                        <Chip
                          label={
                            buyer.address_quality
                          }
                          color={
                            buyer.address_quality ===
                            "GARBLED"
                              ? "error"
                              : "success"
                          }
                        />
                      </TableCell>

                      <TableCell>
                        <Chip
                          label={
                            buyer.vpn_detected
                              ? "Detected"
                              : "Clean"
                          }
                          color={
                            buyer.vpn_detected
                              ? "error"
                              : "success"
                          }
                        />
                      </TableCell>

                      <TableCell>
                        <Chip
                          label={
                            buyer.promo_abuse
                              ? "Yes"
                              : "No"
                          }
                          color={
                            buyer.promo_abuse
                              ? "warning"
                              : "success"
                          }
                        />
                      </TableCell>

                      <TableCell>
                        <Chip
                          label={
                            buyer.delivery_failures
                          }
                          color={
                            buyer.delivery_failures > 3
                              ? "error"
                              : buyer.delivery_failures > 0
                              ? "warning"
                              : "success"
                          }
                        />
                      </TableCell>

                    </TableRow>

                  ))}

                </TableBody>

              </Table>

            </TableContainer>

          </CardContent>

        </Card>

        <Drawer
          anchor="right"
          open={drawerOpen}
          onClose={() =>
            setDrawerOpen(false)
          }
        >

          <Box
            sx={{
              width: 420,
              padding: 3,
            }}
          >

            <Typography
              variant="h5"
              gutterBottom
            >
              Buyer Intelligence Profile
            </Typography>

            <Divider
              sx={{ marginBottom: 2 }}
            />

            {selectedBuyer && (

              <List>

                <ListItem>
                  <ListItemText
                    primary="Buyer Name"
                    secondary={
                      selectedBuyer.name
                    }
                  />
                </ListItem>

                <ListItem>
                  <ListItemText
                    primary="Risk Level"
                    secondary={
                      selectedBuyer.risk_level
                    }
                  />
                </ListItem>

                <ListItem>
                  <ListItemText
                    primary="Risk Score"
                    secondary={
                      selectedBuyer.risk_score
                    }
                  />
                </ListItem>

                <Divider />

                <ListItem>
                  <ListItemText
                    primary="IP Address"
                    secondary={
                      selectedBuyer.ip_address
                    }
                  />
                </ListItem>

                <ListItem>
                  <ListItemText
                    primary="Device Fingerprint"
                    secondary={
                      selectedBuyer.device_fingerprint
                    }
                  />
                </ListItem>

                <ListItem>
                  <ListItemText
                    primary="Google App Instance ID"
                    secondary={
                      selectedBuyer.google_app_instance_id
                    }
                  />
                </ListItem>

                <Divider />

                <ListItem>
                  <ListItemText
                    primary="Risk Indicators"
                    secondary={
                      generateRiskReasons(
                        selectedBuyer
                      ).join(", ")
                    }
                  />
                </ListItem>

                <Divider
                  sx={{
                    marginTop: 2,
                    marginBottom: 2,
                  }}
                />

                <Typography variant="h6">
                  Investigator Summary
                </Typography>

                <Typography variant="body2">
                  This buyer demonstrates
                  elevated fraud behavior based
                  on account linkage patterns,
                  network anomalies, return
                  abuse, suspicious order
                  velocity, and behavioral risk
                  indicators.
                </Typography>

              </List>

            )}

            <Button
              variant="contained"
              color="error"
              fullWidth
              sx={{ marginTop: 3 }}
            >
              Escalate Buyer
            </Button>

          </Box>

        </Drawer>

      </Box>

    </Box>
  );
}

export default Dashboard;
